"use client";

/**
 * Changelog film: the version stamps down, three changes play one after the
 * other (a screen recording, a marked sentence, a struck and replaced
 * phrase), then the end card. About 20 seconds at 1920 by 1080. Every scene
 * is a Better Design video component, cut together with the whip pan
 * transition.
 *
 * Written by Better Design.
 */
import { linearTiming, TransitionSeries } from "@remotion/transitions";
import { Easing } from "remotion";
import { EndCard } from "@/components/bd-video/end-card";
import { RecordingShot } from "@/components/bd-video/recording-shot";
import { StrikeSwap } from "@/components/bd-video/strike-swap";
import { VersionStamp } from "@/components/bd-video/version-stamp";
import { WordMark } from "@/components/bd-video/word-mark";
import { whipPan } from "@/components/bd-video/transition-whip-pan";
import { type VideoTheme, VideoThemeProvider } from "@/lib/bd-video";

/** Every piece of copy and picture the changelog film shows. */
export interface ChangelogFilmContent {
  /** The product name, typed in before the version and set on the end card. */
  name: string;
  /** The version as you want it shown, such as "2.4" or "v4". */
  version: string;
  /** One line under the version, such as the release date. */
  dateLine: string;
  /** First change: a screen recording (.mp4, .webm, .mov) or a still. A placeholder page is drawn when unset. */
  recording?: string;
  /** The capture's pixel size, as ffprobe reports it. */
  recordingSize: { width: number; height: number };
  /** Second change: one sentence, with the phrase inside it that gets marked. */
  markText: string;
  markPhrase: string;
  /** Third change: the sentence reads before, struck, replacement, after. */
  swap: { before: string; struck: string; replacement: string; after: string };
  /** The call to action on the end card button. */
  cta: string;
  /** The web address under the button. */
  url: string;
}

const DEFAULT_CONTENT: ChangelogFilmContent = {
  name: "Your product",
  version: "2.4",
  dateLine: "Available today",
  recordingSize: { width: 1440, height: 900 },
  markText: "Search now finds files by what is inside them",
  markPhrase: "what is inside them",
  swap: { before: "Exports used to take", struck: "a minute", replacement: "two seconds", after: "." },
  cta: "Read the full changelog",
  url: "yourproduct.com/changelog",
};

export interface ChangelogFilmProps {
  content?: Partial<ChangelogFilmContent>;
  theme?: Partial<VideoTheme>;
}

/** Frames per scene, in order: version, recording, marked sentence, swap, end. */
const SCENES = [120, 150, 110, 120, 160] as const;
const CUT = 15;
const cut = () => <TransitionSeries.Transition presentation={whipPan({ direction: "left" })} timing={linearTiming({ durationInFrames: CUT, easing: Easing.bezier(0.7, 0, 0.3, 1) })} />;

/** A release changelog film built from Better Design video components. */
export function ChangelogFilm({ content, theme }: ChangelogFilmProps) {
  const c = { ...DEFAULT_CONTENT, ...content };
  const swap = { ...DEFAULT_CONTENT.swap, ...content?.swap };
  return (
    <VideoThemeProvider theme={theme}>
      <TransitionSeries>
        <TransitionSeries.Sequence durationInFrames={SCENES[0]}>
          <VersionStamp product={c.name} version={c.version} dateLine={c.dateLine} theme={theme} />
        </TransitionSeries.Sequence>
        {cut()}
        <TransitionSeries.Sequence durationInFrames={SCENES[1]}>
          <RecordingShot recording={c.recording} captureSize={c.recordingSize} theme={theme} />
        </TransitionSeries.Sequence>
        {cut()}
        <TransitionSeries.Sequence durationInFrames={SCENES[2]}>
          <WordMark text={c.markText} phrase={c.markPhrase} variant="marker" theme={theme} />
        </TransitionSeries.Sequence>
        {cut()}
        <TransitionSeries.Sequence durationInFrames={SCENES[3]}>
          <StrikeSwap before={swap.before} struck={swap.struck} replacement={swap.replacement} after={swap.after} theme={theme} />
        </TransitionSeries.Sequence>
        {cut()}
        <TransitionSeries.Sequence durationInFrames={SCENES[4]}>
          <EndCard name={c.name} cta={c.cta} url={c.url} theme={theme} />
        </TransitionSeries.Sequence>
      </TransitionSeries>
    </VideoThemeProvider>
  );
}

/** Composition settings. The duration is the scenes minus the four 15-frame cuts. */
export const CHANGELOG_FILM = { durationInFrames: 600, fps: 30, width: 1920, height: 1080 } as const;
